// Ethers CDN fallback - will load from CDN
// This file just loads ethers from CDN and makes it available
document.addEventListener('DOMContentLoaded', function() {
    if (typeof ethers === 'undefined') {
        console.log('Loading ethers from CDN...');
        var script = document.createElement('script');
        script.src = 'https://cdnjs.cloudflare.com/ajax/libs/ethers/6.13.2/ethers.umd.min.js';
        script.onload = function() { console.log('✅ Ethers loaded'); };
        script.onerror = function() { console.error('❌ Failed to load ethers'); };
        document.head.appendChild(script);
    }
});
